import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('render draft invoice with single line', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('DRAFT'));
  assert(output.includes('Alice'));
  assert(output.includes('1 × Widget @ €10.00 = €10.00'));
  assert(output.includes('Total: €12.10'));
});

test('render issued invoice with number', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('INV-2026-0001'));
  assert(output.includes('Alice'));
  assert(output.includes('Total: €12.10'));
  assert(output.includes('Due: 2026-10-31'));
});

test('render invoice with line discount', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('discount: €100.00'));
});

test('render invoice with tier discount', () => {
  const invoice = {
    customerId: 'C-002',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 5 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('discount: €50.00'));
});

test('render invoice without line discount does not show discount line', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(!output.includes('discount:'));
});

test('render invoice with multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [
      { sku: 'ITEM1', name: 'Widget', qty: 2, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
      { sku: 'ITEM2', name: 'Gadget', qty: 1, unitPrice: 500, vatRate: 9, discountPercent: 0 },
    ],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('2 × Widget @ €10.00 = €20.00'));
  assert(output.includes('1 × Gadget @ €5.00 = €5.00'));
});

test('render invoice with VAT', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('VAT: €21.00'));
});

test('render invoice with zero VAT', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 0, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(!output.includes('VAT:'));
});

test('render invoice with voucher', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
    voucher: { code: 'PROMO', amount: 200 },
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('Voucher: €2.00'));
  assert(output.includes('Paid:') === false);
});

test('render invoice without voucher does not show voucher line', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 1000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(!output.includes('Voucher:'));
});

test('render invoice with payments', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'partially_paid',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('Paid: €50.00'));
});

test('render invoice with multiple payments', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'partially_paid',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
    payments: [
      { amount: 3000, date: '2026-10-10' },
      { amount: 2000, date: '2026-10-20' },
    ],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('Paid: €50.00'));
});

test('render invoice without payments does not show paid line', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 }],
  };
  const output = renderInvoiceText(invoice);
  assert(!output.includes('Paid:'));
});

test('render invoice with discount and voucher and payments', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'partially_paid',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'PROMO', amount: 500 },
    payments: [{ amount: 4000, date: '2026-10-15' }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('discount: €1,000.00'));
  assert(output.includes('Voucher: €5.00'));
  assert(output.includes('Due: 2026-10-31'));
  assert(output.includes('Paid: €40.00'));
});

test('render invoice output order', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'partially_paid',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 10 }],
    voucher: { code: 'PROMO', amount: 500 },
    payments: [{ amount: 4000, date: '2026-10-15' }],
  };
  const output = renderInvoiceText(invoice);
  const lines = output.split('\n');
  const invoiceNumberIndex = lines.findIndex(l => l.includes('INV-2026-0001'));
  const customerIndex = lines.findIndex(l => l.includes('Alice'));
  const lineItemIndex = lines.findIndex(l => l.includes('Widget'));
  const vatIndex = lines.findIndex(l => l.includes('VAT:'));
  const voucherIndex = lines.findIndex(l => l.includes('Voucher:'));
  const totalIndex = lines.findIndex(l => l.includes('Total:'));
  const dueIndex = lines.findIndex(l => l.includes('Due:'));
  const paidIndex = lines.findIndex(l => l.includes('Paid:'));

  assert(invoiceNumberIndex < customerIndex);
  assert(customerIndex < lineItemIndex);
  assert(lineItemIndex < vatIndex);
  assert(vatIndex < voucherIndex);
  assert(voucherIndex < totalIndex);
  assert(totalIndex < dueIndex);
  assert(dueIndex < paidIndex);
});

test('render invoice with high quantity (bulk discount)', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    issueDate: '2026-10-01',
    dueDate: '2026-10-31',
    status: 'issued',
    lines: [{ sku: 'ITEM1', name: 'Widget', qty: 150, unitPrice: 100, vatRate: 21, discountPercent: 5 }],
  };
  const output = renderInvoiceText(invoice);
  assert(output.includes('150 × Widget'));
  assert(output.includes('discount: €750.00'));
});

