import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText renders a draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.match(text, /^DRAFT\n/);
  assert.match(text, /Northwind Studio/);
  assert.match(text, /5 × Design work \(hour\) @ €85.00 = €425.00/);
  assert.match(text, /VAT: €/);
  assert.match(text, /Total: €/);
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoice = {
    number: 'INV-2026-0042',
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21, discountPercent: 5 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 5 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[0], 'INV-2026-0042');
  assert.equal(lines[1], 'Northwind Studio');
  assert.match(text, /5 × Design work \(hour\) @ €85.00 = €425.00/);
  assert.match(text, /1 × Logo package @ €1,200.00 = €1,200.00/);
  assert.match(text, /VAT: €/);
  assert.match(text, /Total: €/);
});

test('renderInvoiceText includes all invoice lines', () => {
  const invoice = {
    customerId: 'C-003',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21, discountPercent: 2.5 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21, discountPercent: 2.5 },
      { sku: 'SUPPORT-HOUR', name: 'Support (hour)', qty: 1, unitPrice: 7250, vatRate: 21, discountPercent: 2.5 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines.length, 7);
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  assert.match(lines[2], /2 × Design work \(hour\) @ €85.00 = €170.00/);
  assert.match(lines[3], /3 × Development \(hour\) @ €95.00 = €285.00/);
  assert.match(lines[4], /1 × Support \(hour\) @ €72.50 = €72.50/);
  assert.match(lines[5], /VAT: €/);
  assert.match(lines[6], /Total: €/);
});

